package com.campus.lostfound.config;
import com.campus.lostfound.domain.*;import com.campus.lostfound.repository.*;import com.campus.lostfound.service.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Profile;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Component @Profile("demo") public class DemoData implements CommandLineRunner {
 private final UserRepository users;private final LostReportRepository lost;private final FoundReportRepository found;private final ClaimRepository claims;private final HandoverRepository handovers;private final PasswordEncoder encoder;private final MatchingService matching;
 public DemoData(UserRepository users,LostReportRepository lost,FoundReportRepository found,ClaimRepository claims,HandoverRepository handovers,PasswordEncoder encoder,MatchingService matching){this.users=users;this.lost=lost;this.found=found;this.claims=claims;this.handovers=handovers;this.encoder=encoder;this.matching=matching;}
 @Override @Transactional public void run(String...args){if(users.count()>0)return;List<User> people=new ArrayList<>();String[] names={"Aarav Shah","Mira Patel","Ishan Rao","Anaya Singh","Kabir Mehta","Riya Nair","Dev Menon","Campus Administrator"};String[] depts={"Computer Science","Design","Physics","Economics","Electrical Engineering","Biology","Campus Operations","Administration"};for(int i=0;i<names.length;i++){Role role=i==7?Role.ADMIN:i>=5?Role.STAFF:Role.STUDENT;people.add(users.save(new User(names[i],"demo"+(i+1)+"@campus.example",encoder.encode("CampusDemo2026!"),"CAMPUS-"+(1000+i),depts[i],role)));}
 String[] titles={"Black wireless earbuds case","Blue stainless water bottle","Calculus notebook","Student ID card","Olive canvas backpack","Silver keyring with blue tag","USB-C charger","Red umbrella","Library copy of Dune","Fitness band","Black travel mug","Gray pencil pouch","Wireless mouse","Green scarf","Leather wallet"};String[] cats={"Electronics","Other","Books and Stationery","Identification Cards","Bags and Wallets","Accessories","Electronics","Clothing","Books and Stationery","Electronics","Other","Books and Stationery","Electronics","Clothing","Bags and Wallets"};String[] places={"Main Library","Central Canteen","Academic Block","Computer Science Department","Student Activity Centre","Main Gate","Academic Block","Sports Complex","Main Library","Sports Complex","Central Canteen","Main Library","Computer Science Department","Auditorium","Main Gate"};LocalDate today=LocalDate.now();List<LostReport> lostRows=new ArrayList<>();List<FoundReport> foundRows=new ArrayList<>();for(int i=0;i<15;i++){int reporter=i%5;LostReport l=lost.save(new LostReport(titles[i],"Looking for my "+titles[i].toLowerCase()+". " +(i==0?"Small initials AS inside the case.":"It has a small distinguishing mark."),cats[i],places[i],today.minusDays(i+1),null,people.get(reporter),"10:30 AM"));lostRows.add(l);FoundReport f=found.save(new FoundReport(titles[i],"A "+titles[i].toLowerCase()+" was turned in. Please contact campus staff to verify details.",cats[i],places[i],today.minusDays(i),null,people.get(5+i%2),"11:00 AM","Campus Security Office",i==0?"Initials AS inside the lid":"Private identifying detail recorded with staff"));foundRows.add(f);}
 for(LostReport r:lostRows)matching.match(r);for(FoundReport r:foundRows)matching.match(r);
 for(int i=0;i<4;i++)claims.save(new Claim(foundRows.get(i),people.get(i),"I reported losing a similar item near "+places[i]+".","I can identify a unique scratch and an item stored inside."));
 Claim resolved=new Claim(foundRows.get(4),people.get(4),"I can identify this bag and its contents.","A sewn patch is on the inner pocket.");claims.save(resolved);resolved.review(people.get(7),true,"Verified against private item details");Handover handover=handovers.save(new Handover(resolved,people.get(5),"Campus Security Office",Instant.now().minusSeconds(3600)));handover.confirmOwner();handover.complete();foundRows.get(4).markReturned();
 }
}
